// Normalise direct bakery-order vs standard envelope events
const item = $input.first().json;
const body = item.body || item;

let event = body.event || 'order.created';
let data = body.data || body;

// Format items list into clear readable text
let itemsList = '';
if (Array.isArray(data.items)) {
  itemsList = data.items.map(it => `• ${it.name || it.product_name} x${it.quantity} (Rs. ${Number(it.unit_price || it.price || 0).toLocaleString()})`).join('\n');
} else {
  itemsList = data.items_summary || 'Bakery Items';
}

const totalAmount = (data.financials ? data.financials.total_amount : data.total) || 0;
const customerName = (data.customer ? data.customer.name : data.customer_name) || 'Valued Customer';
const customerPhone = (data.customer ? data.customer.phone : data.phone) || '';
const address = data.delivery_address || data.address || 'Counter Pickup';
const paymentMethod = (data.financials ? data.financials.payment_method : data.payment_method) || 'Cash on Delivery (COD)';
const orderNumber = data.order_number || ('FB-' + (data.order_id || Date.now()));

return {
  json: {
    event: event,
    order_number: orderNumber,
    order_id: data.order_id,
    customer_name: customerName,
    customer_phone: customerPhone,
    delivery_address: address,
    payment_method: paymentMethod,
    total_amount: totalAmount,
    items_formatted: itemsList,
    raw_data: data
  }
};

// Prepare WhatsApp Message for Customer
const d = $input.first().json;

const customerMessage = `🍰 *FRESHCO BAKERS — ORDER CONFIRMATION* 🍰\n\n` +
  `Assalam-o-Alaikum *${d.customer_name}*!\n` +
  `Aapka order receive ho chuka hai aur kitchen mein process ho raha hai.\n\n` +
  `📋 *Order ID:* #${d.order_number}\n` +
  `🎂 *Items:*\n${d.items_formatted}\n\n` +
  `💰 *Total Amount:* Rs. ${Number(d.total_amount).toLocaleString()}\n` +
  `💳 *Payment Method:* ${d.payment_method}\n` +
  `📍 *Delivery Address:* ${d.delivery_address}\n\n` +
  `⏱️ *Estimated Time:* 45 - 60 Minutes\n` +
  `🚚 *Live Track Order:* http://freshcobakers.com/orders/${d.order_id || ''}\n\n` +
  `Thank you for choosing Freshco Bakers!\nFresh bakes, always fresh taste! ❤️`;

// Prepare WhatsApp & Telegram Message for Bakery Owner / Kitchen Display
const ownerMessage = `🔔 *NEW BAKERY ORDER RECEIVED!* 🔔\n\n` +
  `*Order ID:* #${d.order_number}\n` +
  `*Customer:* ${d.customer_name} (${d.customer_phone})\n` +
  `*Type / Address:* ${d.delivery_address}\n` +
  `*Payment:* ${d.payment_method} - *Rs. ${Number(d.total_amount).toLocaleString()}*\n\n` +
  `*Order Details:*\n${d.items_formatted}\n\n` +
  `👉 Open Kitchen POS to accept & start baking!`;

return {
  json: {
    ...d,
    customer_whatsapp_text: customerMessage,
    owner_alert_text: ownerMessage
  }
};

// Prepare Status Update Notification
const d = $input.first().json.raw_data;
const status = d.new_status || 'CONFIRMED';
const orderNumber = d.order_number || ('FB-' + d.order_id);
const customerName = (d.customer ? d.customer.name : 'Valued Customer');
const customerPhone = (d.customer ? d.customer.phone : '');

const statusUrdu = {
  'CONFIRMED': 'Bakery ne aapka order confirm kar liya hai! 🧑‍🍳',
  'PREPARING': 'Aapka order oven mein bake ho raha hai! 🎂🔥',
  'READY': 'Aapka order pack ho kar ready hai! 📦✨',
  'OUT_FOR_DELIVERY': 'Rider order le kar nikal chuka hai! 🛵💨',
  'DELIVERED': 'Order deliver ho gaya hai. Enjoy your delicious treats! 🍰🎉',
  'CANCELLED': 'Aapka order cancel kar diya gaya hai.'
};

const msg = `*FRESHCO BAKERS — ORDER STATUS UPDATE*\n\n` +
  `Dear *${customerName}*,\n` +
  `Order #${orderNumber}: *${statusUrdu[status] || status}*\n\n` +
  `Track status: ${d.tracking_url || 'http://freshcobakers.com'}`;

return {
  json: {
    customer_phone: customerPhone,
    status: status,
    status_message: msg
  }
};

// Low Stock Alert Message
const d = $input.first().json.raw_data;
const msg = `⚠️ *URGENT INVENTORY ALERT — LOW STOCK* ⚠️\n\n` +
  `*Product:* ${d.product_name} (SKU: ${d.sku || 'N/A'})\n` +
  `*Branch:* ${d.branch_name}\n` +
  `*Available Stock:* ${d.current_quantity} units left\n` +
  `*Safety Minimum:* ${d.minimum_quantity} units\n` +
  `*Deficit Needed:* ${d.deficit || 1} units\n\n` +
  `👉 Please create a production batch or restock immediately!`;

return {
  json: {
    alert_text: msg
  }
};

// Custom Cake Message for Baker & Customer
const d = $input.first().json.raw_data;
const msg = `🎂 *NEW CUSTOM CAKE DESIGN REQUEST* 🎂\n\n` +
  `*Request ID:* #${d.cake_id}\n` +
  `*Customer:* ${d.customer ? d.customer.name : 'Customer'} (${d.customer ? d.customer.phone : ''})\n` +
  `*Flavour:* ${d.cake_details ? d.cake_details.flavour : 'Custom'}\n` +
  `*Size / Weight:* ${d.cake_details ? d.cake_details.type : 'Custom'}\n` +
  `*Needed By Date:* ${d.cake_details ? d.cake_details.requested_date : 'Urgent'}\n\n` +
  `👉 Open Admin Panel to review picture & provide quotation quote!`;

return {
  json: {
    alert_text: msg
  }
};
